package com.vignesh.banking.model;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="users")
public class User{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String email; @Column(nullable=false) private String password; private String fullName; @Enumerated(EnumType.STRING) private Role role=Role.CUSTOMER; @OneToMany(mappedBy="owner",cascade=CascadeType.ALL) private List<Account> accounts=new ArrayList<>(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getEmail(){return email;} public void setEmail(String e){email=e;} public String getPassword(){return password;} public void setPassword(String p){password=p;} public String getFullName(){return fullName;} public void setFullName(String n){fullName=n;} public Role getRole(){return role;} public void setRole(Role r){role=r;} public List<Account> getAccounts(){return accounts;} public void setAccounts(List<Account> a){accounts=a;} }
